import { QUOTATIONS } from "../../data/quotations";
import type { Quotation } from "../../types";
import type { PricingRules } from "../../studio/types";
import { usd } from "../../studio/calc";
import { pct, signedPct } from "./shared";

/* Deterministic helpers for the margin screen. The explanation text is built from data, not generated by a model. */

/** Other quotations with the same material or the same region, best matches first. */
export function similarQuotes(q: Quotation): Quotation[] {
  const score = (o: Quotation) => (o.material === q.material ? 2 : 0) + (o.region === q.region ? 2 : 0) + (o.outcome !== "in_progress" ? 1 : 0);
  return QUOTATIONS.filter((o) => o.id !== q.id && o.value > 0 && (o.material === q.material || o.region === q.region)).sort((a, b) => score(b) - score(a) || b.id.localeCompare(a.id));
}

export function winStats(list: Quotation[]): { awarded: number; decided: number; ratePct: number | null } {
  const awarded = list.filter((o) => o.outcome === "awarded").length;
  const decided = awarded + list.filter((o) => o.outcome === "rejected").length;
  return { awarded, decided, ratePct: decided === 0 ? null : (awarded / decided) * 100 };
}

const avg = (xs: number[]) => (xs.length === 0 ? null : xs.reduce((s, x) => s + x, 0) / xs.length);

/** The most specific margin target in the rules for this material and region. */
export function fallbackTarget(rules: PricingRules, q: Quotation) {
  const fits = rules.marginTargets.filter((t) => (t.material === q.material || t.material === "Any") && (t.region === q.region || t.region === "Any"));
  const spec = (t: { material: string; region: string }) => (t.material === "Any" ? 0 : 1) + (t.region === "Any" ? 0 : 1);
  return fits.sort((a, b) => spec(b) - spec(a))[0] ?? null;
}

export function sizeWord(cost: number): "small" | "mid-sized" | "large" {
  if (cost < 5000) return "small";
  if (cost < 25000) return "mid-sized";
  return "large";
}

export function explainRecommendation(q: Quotation, recommendedPct: number, cost: number, rules: PricingRules): string {
  const size = sizeWord(cost);
  const sizeText =
    size === "large"
      ? "Large jobs usually carry volume pressure from the customer, which pulls margin down."
      : size === "small"
        ? "Small jobs carry fixed handling effort, which supports a higher margin."
        : "A job of this size sits in the usual margin range.";
  const sim = similarQuotes(q);
  const awarded = avg(sim.filter((o) => o.outcome === "awarded").map((o) => o.marginPct));
  const rejected = avg(sim.filter((o) => o.outcome === "rejected").map((o) => o.marginPct));
  const history =
    awarded !== null && rejected !== null
      ? `Similar quotes that were won ran at about ${pct(awarded, 1)} margin, and lost ones at about ${pct(rejected, 1)}.`
      : awarded !== null
        ? `Similar quotes that were won ran at about ${pct(awarded, 1)} margin.`
        : "There is not enough decided history for similar quotes.";
  const mod = rules.regionModifiers.find((m) => m.region === q.region);
  const region = mod ? ` Labour in ${q.region} is ${signedPct(mod.labourPct, 0)} against the price book, and that is already inside the cost.` : "";
  return `For ${q.product.toLowerCase()} in ${q.material.toLowerCase()} for a ${q.region} customer, the model recommends a ${pct(recommendedPct, 1)} margin. This is a ${size} job with an estimated cost of ${usd(cost)}. ${sizeText} ${history}${region}`;
}
